import os
import torch


class Config:
    """
    Global configuration for the Dual-View Structural Alignment Regressor (DVSAR).
    """

    # =========================================================================
    # Directories and Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_6"
    SUBMISSION_DIR = "./submission"

    # Metadata Files (Generated by the metadata script)
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Paths for Fine-Tuned Models
    TEXT_MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "fine_tuned_text_model")
    CODE_MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "fine_tuned_code_model")

    # Cache Files for Features
    # Using parquet for efficient storage of feature dataframes
    TRAIN_FEATURES_PATH = os.path.join(WORKING_DIR, "train_features.parquet")
    VAL_FEATURES_PATH = os.path.join(WORKING_DIR, "val_features.parquet")
    TEST_FEATURES_PATH = os.path.join(WORKING_DIR, "test_features.parquet")

    # Final Submission Output
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Model Hyperparameters
    # =========================================================================
    # Backbone Models
    # Text-View: Efficient sentence transformer for semantic similarity
    MODEL_TEXT = "sentence-transformers/all-MiniLM-L6-v2"
    # Code-View: Pre-trained on code to capture syntactic/structural alignment
    MODEL_CODE = "microsoft/codebert-base"

    # Tokenization
    MAX_LEN = 128

    # Stage 1: Contrastive Fine-Tuning Hyperparameters
    # Tuned for A100-40GB GPU
    BATCH_SIZE = 64
    NUM_EPOCHS = 1  # 1 epoch is typically sufficient for alignment on this dataset size
    LEARNING_RATE = 2e-5
    WEIGHT_DECAY = 0.01
    WARMUP_STEPS = 1000

    # Stage 2: LightGBM Regressor Hyperparameters
    # Explicit feature engineering + Tree-based regression
    LGBM_PARAMS = {
        "n_estimators": 2000,
        "learning_rate": 0.05,
        "num_leaves": 63,
        "max_depth": -1,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "objective": "regression",
        "metric": "mse",
        "n_jobs": 12,  # Utilizing available vCPUs
        "verbosity": -1,
        "random_state": 42,
    }

    # =========================================================================
    # Global Settings
    # =========================================================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Ensures that the necessary working and submission directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def get_lgbm_params(cls, **kwargs):
        """
        Returns the LightGBM parameters, allowing for dynamic overrides.

        Args:
            **kwargs: Key-value pairs to override default LGBM_PARAMS.
        """
        params = cls.LGBM_PARAMS.copy()
        params.update(kwargs)
        return params
